import{_ as s,o as a,c as o,a2 as t}from"./chunks/framework.uw_ZoRon.js";const m=JSON.parse('{"title":"Message passing","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/message-passing.md","filePath":"deep-dive/message-passing.md"}'),n={name:"deep-dive/message-passing.md"};function r(i,e,c,h,d,l){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="message-passing" tabindex="-1">Message passing <a class="header-anchor" href="#message-passing" aria-label="Permalink to &quot;Message passing&quot;">​</a></h1><p>Processes in RUSM <strong>share nothing</strong> — separate memories, separate permissions. So they communicate the only safe way: by <strong>copying</strong> bytes through the host. Each process owns a mailbox (an async channel); sending is fire-and-forget, and receiving suspends the receiver until a message arrives. It&#39;s Erlang&#39;s model, made airtight by Wasm&#39;s memory boundary.</p><h2 id="the-flow-of-a-message" tabindex="-1">The flow of a message <a class="header-anchor" href="#the-flow-of-a-message" aria-label="Permalink to &quot;The flow of a message&quot;">​</a></h2><ol><li>The sender builds a message in its own linear memory and calls the host <strong><code>send</code></strong> op (<code>send: func(to: pid, message: list&lt;u8&gt;)</code> in the <code>rusm:runtime</code> actor interface; raw core modules call the equivalent <code>rusm.send</code>).</li><li>The host <strong>copies</strong> those bytes out of the sender&#39;s memory and pushes them onto the target&#39;s mailbox (a Tokio channel). No memory is ever shared.</li><li>The target calls <strong><code>receive</code></strong> (<code>receive: func() -&gt; list&lt;u8&gt;</code>), which awaits the mailbox; the host copies the bytes <strong>into</strong> the target&#39;s memory.</li></ol><h2 id="why-copy-not-share" tabindex="-1">Why copy, not share <a class="header-anchor" href="#why-copy-not-share" aria-label="Permalink to &quot;Why copy, not share&quot;">​</a></h2><p>Sharing memory between instances would break isolation — the whole point of the model. A shared buffer means one process&#39;s bug, or one permission boundary, can reach into another&#39;s memory. Copying keeps every crash and every capability boundary strictly local.</p><p>The messages themselves are ordinary serialized data: the <code>rusm-rs</code>, <code>rusm-ts</code>, and <code>rusm-go</code> guest SDKs all send serde JSON over <strong>one shared wire</strong>, so a Rust, a TypeScript, and a Go guest can message each other transparently.</p><h2 id="receiving-suspends-—-it-never-spins" tabindex="-1">Receiving suspends — it never spins <a class="header-anchor" href="#receiving-suspends-—-it-never-spins" aria-label="Permalink to &quot;Receiving suspends — it never spins&quot;">​</a></h2><p><code>receive()</code> is an async host call. An empty mailbox <strong>parks</strong> the Tokio task (see <a href="/rusm/deep-dive/fibers-and-blocking-to-async">fibers &amp; blocking→async</a>) rather than busy-waiting, so a million processes all blocked on <code>receive</code> cost almost nothing — they&#39;re just idle tasks. That&#39;s exactly what makes &quot;a process per request, per connection, per unit of work&quot; affordable.</p><blockquote><p>Shipped in Phase 2. (Opt-in mailbox depth surfaces in the observer snapshot.)</p></blockquote>',10)])])}const g=s(n,[["render",r]]);export{m as __pageData,g as default};
